/*@ requires \valid(dest) && \valid_read(src); @ requires \exists integer n; @ requires \bytes(dest, n) >= strlen(dest) + strlen(src) + 1; @ ensures \result == dest; @ ensures \forall integer i; @ ensures \result[i] == (i < strlen(dest) ? dest[i] : src[i - strlen(dest)]); @ assigns *dest, *src; @*/ char *cstrcat(char *dest, const char *src) { char *p = dest; while (*p != '\0') p++; while (*src != '\0') { *p = *src; p++; src++; } *p = '\0'; return dest; } int main(void) { char *dest; char *src; cstrcat(dest, src); return 0; }